with cleaned as (select *, coalesce(email, 'Unknown') email_filled, coalesce(level, 'N/A') level_filled from employees where job_title <> 'Intern'), metrics as (select id, full_name, email, dept_id, job_title, level_filled, row_number() over (partition by level order by salary, id) row_seq, round(salary / sum(salary) over (partition by manager_id), 4) salary_share, avg(salary) over (order by salary, id rows between 6 preceding and current row) salary_avg_6, row_number() over (partition by level order by hire_date desc, id) seq_no, avg(salary) over (partition by month(hire_date), manager_id order by salary, id rows between 6 preceding and 1 preceding) salary_avg_6_prior from cleaned), joined as (select e.id, e.full_name, e.email, e.dept_id, e.job_title, e.level_filled, e.row_seq, e.salary_share, e.salary_avg_6, e.seq_no, e.salary_avg_6_prior, b.dept_name, b.location, b.budget from metrics e left join departments b on e.dept_id = b.id), enriched as (select *, sum(salary_share) over (partition by dept_name, job_title order by salary_share, id rows between unbounded preceding and current row) cumulative_salary_share, ntile(3) over (partition by dept_name order by row_seq desc, id) row_seq_bucket, ntile(4) over (partition by job_title order by salary_share desc, id) salary_share_bucket, ntile(5) over (partition by dept_id order by salary_share, id) salary_share_bucket_2, sum(budget) over (order by budget, id rows between unbounded preceding and current row) cumulative_budget from joined where seq_no < 8), with_windows as (select *, row_number() over w_ordered seq_no_2, lag(cumulative_salary_share, 2) over (partition by job_title order by row_seq_bucket, id) prev_cumulative_salary_share from enriched window w_ordered as (order by cumulative_salary_share, id)), enriched_employees as (select id, full_name, dept_id, salary_avg_6, location, salary_share_bucket, salary_share_bucket_2, cumulative_budget, seq_no_2, prev_cumulative_salary_share, count(salary_avg_6_prior) over (partition by job_title order by seq_no, id rows between unbounded preceding and current row) running_count_salary_avg_6_prior, min(salary_avg_6_prior) over (partition by job_title order by seq_no, id rows between unbounded preceding and current row) running_min_salary_avg_6_prior, max(salary_avg_6_prior) over (partition by job_title order by seq_no, id rows between unbounded preceding and current row) running_max_salary_avg_6_prior, sum(salary_avg_6_prior) over (partition by job_title order by seq_no, id rows between unbounded preceding and current row) running_sum_salary_avg_6_prior, round(salary_avg_6 / sum(salary_avg_6) over (partition by job_title), 4) salary_avg_6_share from with_windows), latest as (select *, row_number() over (partition by dept_id order by salary_share_bucket_2 desc nulls first, id) as rank_in_group from enriched_employees qualify rank_in_group = 1) select dept_id, count(*) as num_rows, sort_array(collect_set(location)) as location_list, count_if(location = 'Chiang Mai') as chiang_mai_events, sum(running_min_salary_avg_6_prior) as total_running_min_salary_avg_6_prior from latest group by dept_id order by chiang_mai_events nulls first;
